### 🎬 Passo 3: JavaScript (script.js)

Este JS é simples, mas essencial. Ele adicionará uma interatividade sutil (como um efeito de rolagem suave) que faz a página parecer mais polida e profissional. Copie este código para um arquivo chamado `script.js` **na mesma pasta**.

```javascript
// ---------------------------------------
// SCRIPT DE INTERATIVIDADE SUTIL
// ---------------------------------------

document.addEventListener('DOMContentLoaded', () => {
    console.log("✅ PDFDigest AI Landing Page carregada com sucesso! 🧠");

    // 1. Efeito de Rolagem Suave (Smooth Scrolling)
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            document.querySelector(this.getAttribute('href')).scrollIntoView({
                behavior: 'smooth'
            });
        });
    });

    // 2. Observador de Rolagem (Para adicionar classes em partes da página quando o usuário rola)
    const sections = document.querySelectorAll('section');

    const observerOptions = {
        root: null, // viewport
        rootMargin: '0px',
        threshold: 0.1 // Quando 10% do elemento estiver visível
    };

    const observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                // Adiciona uma classe quando a seção entra na tela
                entry.target.classList.add('is-visible');
                // Opcional: Para parar de observar após ser visível
                // observer.unobserve(entry.target); 
            } else {
                entry.target.classList.remove('is-visible');
            }
        });
    }, observerOptions);

    sections.forEach(section => {
        observer.observe(section);
    });

    // Nota: Você pode adicionar animações CSS baseadas na classe 'is-visible' no seu style.css para um efeito ainda mais dramático!
});
```

